<?php
$id=(int)($_GET['id']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){requirePermission('returns');checkCsrf();$action=$_POST['action']??'';$reason=trim($_POST['reason']??'');try{$pdo->beginTransaction();$st=$pdo->prepare('SELECT * FROM sales WHERE id=? FOR UPDATE');$st->execute([$id]);$s=$st->fetch();if(!$s)throw new Exception('Venda não encontrada.');if(in_array($s['status'],['cancelled','returned'],true))throw new Exception('Esta venda já foi estornada.');$items=$pdo->prepare('SELECT si.*,p.name FROM sale_items si JOIN products p ON p.id=si.product_id WHERE sale_id=?');$items->execute([$id]);$items=$items->fetchAll();$totalReturn=0;$returnLines=[];
if($action==='cancel'){foreach($items as $i){$already=$pdo->prepare('SELECT COALESCE(SUM(ri.quantity),0) FROM sale_return_items ri JOIN sale_returns r ON r.id=ri.return_id WHERE r.sale_id=? AND ri.product_id=?');$already->execute([$id,$i['product_id']]);$remaining=max(0,$i['quantity']-(int)$already->fetchColumn());if($remaining){$line=$remaining*$i['unit_price'];$totalReturn+=$line;$returnLines[]=[$i,$remaining,$line];}}$newStatus='cancelled';$rtype='cancel';}
elseif($action==='return'){$rtype='return';$newStatus='partially_returned';foreach($items as $i){$q=max(0,(int)($_POST['qty'][$i['id']]??0));if(!$q)continue;$already=$pdo->prepare('SELECT COALESCE(SUM(ri.quantity),0) FROM sale_return_items ri JOIN sale_returns r ON r.id=ri.return_id WHERE r.sale_id=? AND ri.product_id=?');$already->execute([$id,$i['product_id']]);$available=$i['quantity']-(int)$already->fetchColumn();if($q>$available)throw new Exception('Quantidade de devolução inválida para '.$i['name']);$line=$q*$i['unit_price'];$totalReturn+=$line;$returnLines[]=[$i,$q,$line];}if(!$returnLines)throw new Exception('Informe ao menos um item para devolução.');}
else throw new Exception('Ação inválida.');
if(!$reason)$reason=$action==='cancel'?'Cancelamento da venda':'Devolução de mercadoria';$pdo->prepare('INSERT INTO sale_returns(sale_id,user_id,type,total,reason) VALUES(?,?,?,?,?)')->execute([$id,$_SESSION['user']['id'],$rtype,$totalReturn,$reason]);$rid=$pdo->lastInsertId();foreach($returnLines as [$i,$q,$line]){$pdo->prepare('INSERT INTO sale_return_items(return_id,product_id,quantity,unit_price,total) VALUES(?,?,?,?,?)')->execute([$rid,$i['product_id'],$q,$i['unit_price'],$line]);$pdo->prepare('UPDATE products SET stock=stock+? WHERE id=?')->execute([$q,$i['product_id']]);$pdo->prepare('INSERT INTO stock_movements(product_id,user_id,type,quantity,reference,notes) VALUES(?,? ,"return",?,?,?)')->execute([$i['product_id'],$_SESSION['user']['id'],$q,'RET-'.$rid,$reason]);}
if($action==='return'){$chk=$pdo->prepare('SELECT COALESCE(SUM(ri.quantity),0) returned, (SELECT COALESCE(SUM(quantity),0) FROM sale_items WHERE sale_id=?) sold FROM sale_return_items ri JOIN sale_returns r ON r.id=ri.return_id WHERE r.sale_id=?');$chk->execute([$id,$id]);$z=$chk->fetch();if((int)$z['returned']>=(int)$z['sold'])$newStatus='returned';}
$pdo->prepare('UPDATE sales SET status=? WHERE id=?')->execute([$newStatus,$id]);$pdo->prepare('UPDATE accounts_receivable SET status="cancelled" WHERE sale_id=? AND status="open"')->execute([$id]);audit($pdo,$action==='cancel'?'cancel':'return','sale',$id,$reason);$pdo->commit();flash('success',$action==='cancel'?'Venda cancelada e estoque recomposto.':'Devolução registrada e estoque recomposto.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error',$e->getMessage());}redirect('index.php?page=sale_view&id='.$id);}
$st=$pdo->prepare("SELECT s.*,c.name customer,c.document,c.phone,u.name seller FROM sales s LEFT JOIN customers c ON c.id=s.customer_id JOIN users u ON u.id=s.user_id WHERE s.id=?");$st->execute([$id]);$sale=$st->fetch();if(!$sale){flash('error','Venda não encontrada.');redirect('index.php?page=sales');}$it=$pdo->prepare('SELECT si.*,p.name,p.sku FROM sale_items si JOIN products p ON p.id=si.product_id WHERE sale_id=?');$it->execute([$id]);$items=$it->fetchAll();$returned=saleReturnedTotal($pdo,$id);$payments=salePayments($pdo,$id);$title='Venda #'.$id;require __DIR__.'/../../includes/header.php';?>
<div class="page-head"><div><h1>Venda #<?=$id?></h1><p><?=date('d/m/Y H:i',strtotime($sale['created_at']))?> · <?=e($sale['seller'])?> · <span class="badge <?=$sale['status']==='completed'?'ok':'danger'?>"><?=e($sale['status'])?></span></p></div><button class="btn" onclick="window.print()">Imprimir cupom 80mm</button></div>
<div class="grid two"><section class="panel receipt"><div class="receipt-brand"><h2><?=e(setting($pdo,'company_name','Dreamlast Comércio'))?></h2><p><?=e(setting($pdo,'company_address',''))?></p><small><?=e(setting($pdo,'company_document',''))?> · <?=e(setting($pdo,'company_phone',''))?></small></div><p><strong>Cliente:</strong> <?=e($sale['customer']?:'Consumidor final')?></p><table><thead><tr><th>Item</th><th>Qtd.</th><th>Unit.</th><th>Total</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><?=e($i['name'])?><small><?=e($i['sku'])?></small></td><td><?=$i['quantity']?></td><td><?=money($i['unit_price'])?></td><td><?=money($i['total'])?></td></tr><?php endforeach;?></tbody></table><div class="receipt-totals"><p>Subtotal <strong><?=money($sale['subtotal'])?></strong></p><p>Desconto <strong><?=money($sale['discount'])?></strong></p><p class="final">TOTAL <strong><?=money($sale['total'])?></strong></p><?php if($returned>0):?><p>Estornado <strong>- <?=money($returned)?></strong></p><p>Valor líquido <strong><?=money(max(0,$sale['total']-$returned))?></strong></p><?php endif;?><?php if($sale['change_amount']>0):?><p>Troco <strong><?=money($sale['change_amount'])?></strong></p><?php endif;?></div><div class="receipt-payments"><strong>Formas de pagamento</strong><?php foreach($payments as $pay):?><p><span><?=e(paymentLabel($pay['method']))?></span><b><?=money($pay['amount'])?></b></p><?php endforeach;?></div><div class="receipt-footer"><?=e(setting($pdo,'receipt_footer','Obrigado pela preferência!'))?></div></section>
<?php if(can('returns')&&!in_array($sale['status'],['cancelled','returned'],true)):?><section class="panel no-print"><h2>Pós-venda</h2><p>Devoluções recompõem o estoque automaticamente.</p><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="return"><table><thead><tr><th>Produto</th><th>Qtd. devolver</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><?=e($i['name'])?></td><td><input type="number" name="qty[<?=$i['id']?>]" min="0" max="<?=$i['quantity']?>" value="0"></td></tr><?php endforeach;?></tbody></table><label>Motivo<input name="reason" placeholder="Ex.: troca de tamanho, defeito..."></label><button class="btn">Registrar devolução</button></form><hr><form method="post" class="stack" onsubmit="return confirm('Cancelar toda a venda e devolver os itens restantes ao estoque?')"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="cancel"><label>Motivo do cancelamento<input name="reason" required></label><button class="btn danger-btn">Cancelar venda</button></form></section><?php endif;?></div><?php require __DIR__.'/../../includes/footer.php';?>
